const categoryIcons={'Salário':'▣','Freelance':'✦','Moradia':'⌂','Alimentação':'◇','Saúde':'＋','Transporte':'➜','Lazer':'☆','Educação':'▤','Outros':'○'};
const limits={Alimentação:1000,Moradia:2200,Transporte:600,Lazer:450,Saúde:400};
